import {
	createMcpExtension,
	type ExtensionFactory,
	type ExtensionRunner,
	type ExtensionToolContext,
	type ToolDefinition,
} from "@earendil-works/pi-coding-agent";
import {
	defineExtension,
	defineTool,
	type Registry,
	type ToolRegistration,
} from "@earendil-works/pi-durable";
import { SchemaPort } from "./schema-port.ts";

const schemaPort = new SchemaPort();

type JsonValue = string | number | boolean | null | { [key: string]: JsonValue } | JsonValue[];

export type NestedToolExecutor = (
	callerId: string,
	name: string,
	args: unknown,
	options?: { signal?: AbortSignal },
) => Promise<{
	toolCall: { type: "toolCall"; id: string; name: string; arguments: unknown };
	result: {
		content: Array<{ type: "text"; text: string }>;
		details: unknown;
		structuredOutput?: unknown;
	};
	isError: boolean;
}>;

/** Safe type guard checking whether an object has an output stream function. */
export function hasOutput(api: unknown): api is { output(text: string): void } {
	return (
		typeof api === "object" &&
		api !== null &&
		"output" in api &&
		typeof (api as { output: unknown }).output === "function"
	);
}

/** Returns the standard built-in extension factories provided by Pi. */
export function createStandardExtensionFactories(): ExtensionFactory[] {
	return [createMcpExtension()];
}

/** Adapts an extension ToolDefinition to a Durable ToolRegistration without type escape hatches. */
export function adaptExtensionTool(
	toolDef: ToolDefinition,
	executeToolFn: NestedToolExecutor,
	createToolContext?: (callId: string) => ExtensionToolContext,
	getExtensionRunner?: () => ExtensionRunner | undefined,
): ToolRegistration {
	const exposure = toolDef.exposure as string | undefined;
	const isDeferred = exposure === "deferred";
	const callers =
		exposure === "model-only"
			? (["model"] as const)
			: exposure === "codemode" || exposure === "codemode-deferred"
				? (["tools"] as const)
				: exposure === "hidden"
					? ([] as const)
					: (["model", "tools"] as const);

	return defineTool({
		name: toolDef.name,
		description: toolDef.description,
		parameters: toolDef.parameters,
		callers,
		...(toolDef.promptSnippet ? { promptSnippet: toolDef.promptSnippet } : {}),
		...(toolDef.promptGuidelines?.length ? { promptGuidelines: toolDef.promptGuidelines } : {}),
		...(isDeferred ? { deferred: true } : {}),
		...(toolDef.outputSchema
			? {
					outputSchema: toolDef.outputSchema as import("@sinclair/typebox").TSchema,
					structuredOutputSchema: toolDef.outputSchema as import("@sinclair/typebox").TSchema,
				}
			: {}),
		async execute(args, api, runtimeContext) {
			const runner = getExtensionRunner?.();
			const abortSignal = (runtimeContext as { abortSignal?: AbortSignal } | undefined)?.abortSignal;
			if (runner?.hasHandlers("tool_call")) {
				const hookResult = await runner.emitToolCall({
					type: "tool_call",
					toolName: toolDef.name,
					toolCallId: api.callId,
					input: (args ?? {}) as Record<string, unknown>,
				});
				if (hookResult?.block) {
					const blockContent = [{ type: "text" as const, text: `Tool execution blocked: ${hookResult.reason ?? "policy"}` }];
					return {
						output: blockContent,
						isError: true,
					};
				}
			}

			const base = createToolContext?.(api.callId);
			const descriptors: PropertyDescriptorMap = {
				...Object.getOwnPropertyDescriptors(base ?? {}),
				tools: {
					get: () => base?.tools ?? [],
					configurable: true,
					enumerable: true,
				},
				executeTool: {
					value: async (name: string, nestedArgs: unknown, options?: { signal?: AbortSignal }) =>
						base?.executeTool
							? base.executeTool(name, nestedArgs, options)
							: executeToolFn(api.callId, name, nestedArgs, options),
					configurable: true,
					enumerable: true,
					writable: true,
				},
			};
			const ctx = Object.defineProperties({}, descriptors) as ExtensionToolContext;
			const coercedArgs = schemaPort.coerce(toolDef.parameters, args);

			try {
				const result = await toolDef.execute(
					api.callId,
					coercedArgs,
					abortSignal,
					(update) => {
						if (update?.content && hasOutput(api)) {
							const textChunks = update.content
								.filter((c): c is { type: "text"; text: string } => c.type === "text")
								.map((c) => c.text)
								.join("");
							if (textChunks.length > 0) api.output(textChunks);
						}
					},
					ctx,
				);

				if (runner?.hasHandlers("tool_result")) {
					await runner.emitToolResult({
						type: "tool_result",
						toolName: toolDef.name,
						toolCallId: api.callId,
						input: (args ?? {}) as Record<string, unknown>,
						content: result.content,
						details: (result.details ?? undefined) as JsonValue | undefined,
						isError: result.isError ?? false,
					});
				}

				const structuredOutput =
					(result as { structuredContent?: unknown }).structuredContent !== undefined
						? (result as { structuredContent?: unknown }).structuredContent
						: (result as { structuredOutput?: unknown }).structuredOutput;

				return {
					output: result.content,
					isError: result.isError,
					details: (result.details ?? undefined) as JsonValue | undefined,
					...(structuredOutput !== undefined ? { structuredOutput: structuredOutput as JsonValue } : {}),
				};
			} catch (err: unknown) {
				const message = err instanceof Error ? err.message : String(err);
				const errorContent = [{ type: "text" as const, text: message }];
				if (runner?.hasHandlers("tool_result")) {
					await runner.emitToolResult({
						type: "tool_result",
						toolName: toolDef.name,
						toolCallId: api.callId,
						input: (args ?? {}) as Record<string, unknown>,
						content: errorContent,
						details: undefined,
						isError: true,
					});
				}
				return {
					output: errorContent,
					isError: true,
				};
			}
		},
	});
}

/** Installs adapted tools as a dynamic extension into the Durable Registry. */
export function installExtensionTools(registry: Registry, tools: ToolRegistration[]): void {
	if (tools.length === 0) return;
	registry.install(defineExtension({ name: "extension-tools", tools }));
}
